:root {
  --color-bg: #f0f2f5;
  --color-surface: #ffffff;
  --color-primary: #5b4fcf;
  --color-primary-hover: #4a3fb8;
  --color-primary-active: #3a2fa0;
  --color-primary-light: #ede9fc;
  --color-text: #1a1a2e;
  --color-text-muted: #5a5a7a;
  --color-border: #d0d4e8;
  --color-border-focus: #5b4fcf;
  --color-error: #c0392b;
  --color-error-bg: #fdf3f2;
  --color-success: #1a6b3c;
  --color-success-bg: #edfaf3;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 4px 24px rgba(91, 79, 207, 0.10), 0 1px 4px rgba(0,0,0,0.06);
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -999px;
  left: 16px;
  z-index: 9999;
  background: var(--color-primary);
  color: #fff;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
}
.skip-link:focus {
  top: 16px;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* ===== Screen-reader only utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Layout ===== */
body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.page-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* ===== Header ===== */
.page-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px 32px;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}

.logo {
  font-size: 1.4rem;
}

.logo-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--color-primary);
}

/* ===== Main / Card ===== */
main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
}

.card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 44px 48px;
  width: 100%;
  max-width: 520px;
}

.card h1 {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--color-text);
  margin-bottom: 8px;
}

.card-description {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 28px;
}

/* ===== Required Note ===== */
.required-note {
  font-size: 0.85rem;
  color: var(--color-text-muted);
  margin-bottom: 24px;
}

.required-star {
  color: var(--color-error);
  font-weight: 700;
  margin-left: 1px;
}

/* ===== Form Field ===== */
.form-field {
  margin-bottom: 32px;
}

/* ===== Fieldset / Legend ===== */
fieldset {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: border-color 0.2s;
}

fieldset:focus-within {
  border-color: var(--color-border-focus);
}

legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.4;
  padding: 0 8px;
  margin-bottom: 4px; /* visual gap between legend and options */
}

/* ===== Radio Options ===== */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 16px;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  padding: 14px 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  transition: background 0.15s, border-color 0.15s;
  position: relative;
  user-select: none;
}

.radio-label:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

/* Hide native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  margin: 0;
}

/* Custom radio ring */
.radio-custom {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  min-width: 20px;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-surface);
  transition: border-color 0.15s, background 0.15s;
}

.radio-custom::after {
  content: "";
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-primary);
  opacity: 0;
  transform: scale(0.5);
  transition: opacity 0.15s, transform 0.15s;
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--color-primary);
  background: var(--color-primary-light);
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  opacity: 1;
  transform: scale(1);
}

/* Checked label styling */
.radio-label:has(input[type="radio"]:checked) {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

/* Focus visible ring — applied to the row */
.radio-label input[type="radio"]:focus-visible ~ .radio-custom {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
  border-color: var(--color-primary);
}

/* Radio text */
.radio-text {
  font-size: 0.975rem;
  font-weight: 500;
  color: var(--color-text);
  line-height: 1.4;
}

/* ===== Error state ===== */
fieldset[data-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

.field-error {
  font-size: 0.875rem;
  color: var(--color-error);
  font-weight: 600;
  margin-top: 14px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.field-error::before {
  content: "⚠";
  flex-shrink: 0;
  font-size: 1rem;
  line-height: 1.3;
}

/* ===== Submit Button ===== */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 24px;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  letter-spacing: 0.01em;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 2px 8px rgba(91, 79, 207, 0.25);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 16px rgba(91, 79, 207, 0.35);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
  box-shadow: none;
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ===== Success Banner ===== */
.success-banner {
  margin-top: 20px;
  padding: 14px 16px;
  background: var(--color-success-bg);
  border: 1px solid #a3d9be;
  border-radius: var(--radius-sm);
  color: var(--color-success);
  font-size: 0.95rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ===== Forced colors (high-contrast) ===== */
@media (forced-colors: active) {
  .radio-custom {
    forced-color-adjust: none;
    border-color: ButtonText;
    background: Field;
  }
  .radio-label input[type="radio"]:checked ~ .radio-custom {
    border-color: Highlight;
    background: Highlight;
  }
  .radio-custom::after {
    background: HighlightText;
  }
  .btn-submit {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }
}

/* ===== Reflow / narrow viewport ===== */
@media (max-width: 560px) {
  .card {
    padding: 28px 20px;
    border-radius: var(--radius-md);
  }

  .card h1 {
    font-size: 1.35rem;
  }

  fieldset {
    padding: 16px;
  }
}
