+  background: var(--color-surface);
+  transition: border-color 0.15s, background 0.15s;
+}
+
+.radio-custom::after {
+  content: "";
+  display: block;
+  width: 10px;
+  height: 10px;
+  border-radius: 50%;
+  background: var(--color-primary);
+  opacity: 0;
+  transform: scale(0.5);
+  transition: opacity 0.15s, transform 0.15s;
+}
+
+/* Checked state */
+.radio-label input[type="radio"]:checked ~ .radio-custom {
+  border-color: var(--color-primary);
+  background: var(--color-primary-light);
+}
+
+.radio-label input[type="radio"]:checked ~ .radio-custom::after {
+  opacity: 1;
+  transform: scale(1);
+}
+
+/* Checked label styling */
+.radio-label:has(input[type="radio"]:checked) {
+  background: var(--color-primary-light);
+  border-color: var(--color-primary);
+}
+
+/* Focus visible ring — applied to the row */
+.radio-label input[type="radio"]:focus-visible ~ .radio-custom {
+  outline: 3px solid var(--color-border-focus);
+  outline-offset: 2px;
+  border-color: var(--color-primary);
+}
+
+/* Radio text */
+.radio-text {
+  font-size: 0.975rem;
+  font-weight: 500;
+  color: var(--color-text);
+  line-height: 1.4;
+}
+
+/* ===== Error state ===== */
+fieldset[data-invalid="true"] {
+  border-color: var(--color-error);
+  background: var(--color-error-bg);
+}
+
+.field-error {
+  font-size: 0.875rem;
+  color: var(--color-error);
+  font-weight: 600;
+  margin-top: 14px;
+  display: flex;
+  align-items: flex-start;
+  gap: 6px;
+}
+
+.field-error::before {
+  content: "⚠";
+  flex-shrink: 0;
+  font-size: 1rem;
+  line-height: 1.3;
+}
+
+/* ===== Submit Button ===== */
+.btn-submit {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  width: 100%;
+  padding: 14px 24px;
+  background: var(--color-primary);
+  color: #fff;
+  font-family: var(--font-sans);
+  font-size: 1rem;
+  font-weight: 700;
+  border: none;
+  border-radius: var(--radius-sm);
+  cursor: pointer;
+  letter-spacing: 0.01em;
+  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
+  box-shadow: 0 2px 8px rgba(91, 79, 207, 0.25);
+}
+
+.btn-submit:hover {
+  background: var(--color-primary-hover);
+  box-shadow: 0 4px 16px rgba(91, 79, 207, 0.35);
+}
+
+.btn-submit:active {
+  background: var(--color-primary-active);
+  transform: translateY(1px);
+  box-shadow: none;
+}
+
+.btn-submit:focus-visible {
+  outline: 3px solid var(--color-border-focus);
+  outline-offset: 3px;
+}
+
+/* ===== Success Banner ===== */
+.success-banner {
+  margin-top: 20px;
+  padding: 14px 16px;
+  background: var(--color-success-bg);
+  border: 1px solid #a3d9be;
+  border-radius: var(--radius-sm);
+  color: var(--color-success);
+  font-size: 0.95rem;
+  font-weight: 600;
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+/* ===== Reduced motion ===== */
